css:
@page {
    size: A4;
    margin: 1cm;
}

.items-table {
    width: 100%;
    border-collapse: collapse;
}

.items-table th,
.items-table td {
    border: 1px solid black;
    padding: 5px;
}

.final-amount {
    font-size: 20px;
    font-weight: bold;
}

.damage-banner {
    font-weight: bold;
    border: 1px solid black;
    padding: 8px;
    text-align: center;
}

@media print {
    .interactive {
        display: none !important;
    }
}
